<script setup>
import { Head, useForm } from '@inertiajs/vue3';
import { ref } from 'vue';
import HrmsLayout from '@/Layouts/HrmsLayout.vue';
import HrmsStatus from '@/Components/HrmsStatus.vue';
defineProps({ logs:Array, employees:Array, canManage:Boolean });
const show = ref(false);
const form = useForm({ employee_id:'',work_date:new Date().toISOString().slice(0,10),status:'present',worked_hours:8,note:'' });
const save = () => form.post(route('attendance.store'),{onSuccess:()=>{show.value=false;form.reset();}});
const date = v => v ? new Date(v).toLocaleDateString('ar-SA') : '—';
</script>
<template><Head title="الحضور" /><HrmsLayout title="الحضور والانصراف" subtitle="سجل الأيام وساعات العمل والغياب."><template #actions><button v-if="canManage" class="btn-primary" @click="show=!show">تسجيل حضور</button></template>
    <section v-if="show && canManage" class="panel mb-6 p-5"><h2 class="mb-4 text-lg font-bold text-[#1F3A5F]">سجل حضور جديد</h2><form class="grid gap-4 sm:grid-cols-2 xl:grid-cols-4" @submit.prevent="save"><div><label class="label" for="employee_id">الموظف</label><select id="employee_id" v-model="form.employee_id" class="field" required><option value="">اختر موظفًا</option><option v-for="e in employees" :key="e.id" :value="e.id">{{ e.first_name }} {{ e.last_name }}</option></select></div><div><label class="label" for="work_date">التاريخ</label><input id="work_date" type="date" v-model="form.work_date" class="field" required></div><div><label class="label" for="status">الحالة</label><select id="status" v-model="form.status" class="field"><option value="present">حاضر</option><option value="absent">غائب</option><option value="leave">إجازة</option><option value="holiday">عطلة</option></select></div><div><label class="label" for="hours">الساعات</label><input id="hours" type="number" min="0" max="24" step="0.25" v-model.number="form.worked_hours" class="field"></div><div class="sm:col-span-2 xl:col-span-4"><label class="label" for="note">ملاحظة</label><input id="note" v-model.trim="form.note" class="field"></div><p v-if="Object.keys(form.errors).length" class="error sm:col-span-2">{{ Object.values(form.errors)[0] }}</p><div class="sm:col-span-2 xl:col-span-4"><button class="btn-primary" :disabled="form.processing">حفظ السجل</button></div></form></section>
    <section class="panel overflow-hidden"><div class="border-b border-slate-100 px-5 py-4"><h2 class="text-lg font-bold text-[#1F3A5F]">آخر السجلات</h2></div><div class="overflow-x-auto"><table class="w-full min-w-[620px] text-right"><thead class="table-head"><tr><th class="px-4 py-3">الموظف</th><th class="px-4 py-3">التاريخ</th><th class="px-4 py-3">الحالة</th><th class="px-4 py-3">ساعات العمل</th><th class="px-4 py-3">ملاحظة</th></tr></thead><tbody><tr v-for="log in logs" :key="log.id"><td class="table-cell font-semibold">{{ log.employee?.first_name }} {{ log.employee?.last_name }}</td><td class="table-cell">{{ date(log.work_date) }}</td><td class="table-cell"><HrmsStatus :value="log.status" /></td><td class="table-cell">{{ log.worked_hours }}</td><td class="table-cell text-slate-500">{{ log.note || '—' }}</td></tr></tbody></table></div><p v-if="!logs.length" class="p-8 text-sm text-slate-500">لا توجد سجلات حضور حتى الآن.</p></section>
</HrmsLayout></template>
